alter policy highlights_own on public.highlights using (user_id = auth.uid() and public.is_active_student()) with check (user_id = auth.uid() and public.is_active_student());
alter policy reading_positions_own on public.reading_positions using (user_id = auth.uid() and public.is_active_student()) with check (user_id = auth.uid() and public.is_active_student());
alter policy push_subscriptions_own on public.push_subscriptions using (user_id = auth.uid() and public.is_active_student()) with check (user_id = auth.uid() and public.is_active_student());
alter policy profiles_select on public.profiles using (user_id = auth.uid() or public.is_staff());
alter policy "owner projects" on public.projects using (owner_id = auth.uid()) with check (owner_id = auth.uid());
alter policy "owner sources" on public.sources using (owner_id = auth.uid() and (project_id is null or project_id in (select projects.id from public.projects where projects.owner_id = auth.uid()))) with check (owner_id = auth.uid() and (project_id is null or project_id in (select projects.id from public.projects where projects.owner_id = auth.uid())));
alter policy "owner chapters" on public.chapters using (owner_id = auth.uid() and (project_id is null or project_id in (select projects.id from public.projects where projects.owner_id = auth.uid()))) with check (owner_id = auth.uid() and (project_id is null or project_id in (select projects.id from public.projects where projects.owner_id = auth.uid())));
alter policy "owner documents" on public.documents using (owner_id = auth.uid() and (project_id is null or project_id in (select projects.id from public.projects where projects.owner_id = auth.uid()))) with check (owner_id = auth.uid() and (project_id is null or project_id in (select projects.id from public.projects where projects.owner_id = auth.uid())));
